def flatten(x):
    """Turn nested lists and tuples into one flat list, in order.

    Strings, bytes and dicts are leaves and are kept whole.
    """
    out = []
    for item in x:
        if isinstance(item, (list, tuple)):
            out.extend(flatten(item))
        else:
            out.append(item)
    return out
